mapper.update:
update dish
name = #{name}, category_id = #{categoryId}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select d.id, d.name, d.category_id, d.price, d.image, d.description, d.status, d.update_time, c.name as category_name from dish d left join category c on d.category_id = c.id
and d.name like concat('%', #{name}, '%')
and d.category_id = #{categoryId}
and d.status = #{status}
order by d.create_time desc

select id, name, category_id, price, image, description, status, create_time, update_time, create_user, update_user from dish
and name like concat('%', #{name}, '%')
and category_id = #{categoryId}
and status = #{status}
order by create_time desc
